function deckStats(n){
  const dw=deckWords(n);let seen=0, mastered=0;
  dw.forEach(w=>{const p=progress[w.id];if(p?.seen)seen++;if((p?.level||0)>=4)mastered++});
  return {seen,mastered,total:dw.length,pct:dw.length?Math.round(seen/dw.length*100):0};
}
function globalStats(){
  let seen=0,mastered=0,weak=0,due=0,fav=0;
  words.forEach(w=>{const p=progress[w.id];if(!p)return;if(p.seen)seen++;if(p.level>=4)mastered++;if(p.wrong>p.correct&&p.seen)weak++;if(p.due&&p.due<=now())due++;if(p.fav)fav++});
  return {seen,mastered,weak,due,fav};
}
