function toggleFav(id){const p=pstate(id);p.fav=!p.fav;saveProgress();openDetail(id)}
function speak(t){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang="en-US";u.rate=.9;speechSynthesis.speak(u)}catch(e){toast("此瀏覽器無法朗讀")}}
function toast(t){const el=document.getElementById("toast");el.textContent=t;el.classList.remove("hidden");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add("hidden"),2200)}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function attr(s){return esc(s)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function seededLocalShuffle(a,seed){a=[...a];let x=seed||1;for(let i=a.length-1;i>0;i--){x=(x*9301+49297)%233280;let j=x%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function chunk(a,n){let r=[];for(let i=0;i<a.length;i+=n)r.push(a.slice(i,i+n));return r}
function escapeRegExp(s){return String(s).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}

function idbOpen(){return new Promise((res,rej)=>{try{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
async function idbGet(k){try{const db=await idbOpen();return await new Promise((res,rej)=>{const tx=db.transaction(STORE,"readonly"),r=tx.objectStore(STORE).get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}catch(e){return null}}
async function idbSet(k,v){try{const db=await idbOpen();return await new Promise((res,rej)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).put(v,k);tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error)})}catch(e){return false}}
async function idbDel(k){try{const db=await idbOpen();return await new Promise((res)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).delete(k);tx.oncomplete=()=>res(true);tx.onerror=()=>res(false)})}catch(e){return false}}

async function loadFull(){
  const btns=[...document.querySelectorAll('[data-action="load-full"]')];btns.forEach(b=>{b.disabled=true;b.innerHTML='<span class="loader"></span> 載入中'});
  toast("正在下載並嚴格篩選字庫…");
  let lastErr=null;
  for(const url of FULL_URLS){
    try{
      const r=await fetch(url,{cache:"no-store",mode:"cors"});
      if(!r.ok)throw new Error("HTTP "+r.status);
      const raw=await r.json();
      const selected=select2000(raw);
      words=selected;fullData=true;await idbSet(DATA_KEY,selected);toast("嚴格高分字庫載入完成");show(currentScreen==="settings"?"settings":"home");return;
    }catch(e){lastErr=e}
  }
  btns.forEach(b=>{b.disabled=false;b.textContent="載入嚴格高分字庫"});
  toast("下載被手機瀏覽器阻擋，可改用「匯入資料集 JSON」");
  if(currentScreen==="settings")renderSettings(); else renderHome();
}
async function importDatasetFile(file){
  try{
    const raw=JSON.parse(await file.text());const selected=select2000(raw);words=selected;fullData=true;await idbSet(DATA_KEY,selected);toast("嚴格高分字庫匯入完成");show("home")
  }catch(e){toast("資料集格式不正確")}
}
async function clearData(){await idbDel(DATA_KEY);words=BUILTIN.map((w,i)=>normalizeBuiltin(w,i));fullData=false;toast("已回到 50 字離線模式");show("settings")}
function exportProgress(){
  const blob=new Blob([JSON.stringify({version:2,progress,settings,exportedAt:new Date().toISOString()},null,2)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="toeic900-progress.json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)
}
async function importProgressFile(file){try{const x=JSON.parse(await file.text());if(!x.progress)throw 0;progress=x.progress;if(x.settings)settings=Object.assign(settings,x.settings);saveProgress();saveSettings();applyTheme();toast("進度匯入完成");show("home")}catch(e){toast("進度檔格式不正確")}}
function resetProgress(){if(confirm("確定要清除全部學習紀錄？此動作無法復原。")){progress={};saveProgress();toast("學習紀錄已清除");show("home")}}
function applyTheme(){document.documentElement.dataset.theme=settings.theme}
function toggleTheme(){settings.theme=settings.theme==="dark"?"light":"dark";saveSettings();applyTheme()}

document.addEventListener("click",e=>{
  const b=e.target.closest("[data-action]");if(!b)return;
  const a=b.dataset.action;
  if(a==="open-deck"){currentDeck=Number(b.dataset.deck)||1;resetDeckFilters();show("deck")}
  else if(a==="open-decks"||a==="back-decks")show("decks");
  else if(a==="back-deck")show("deck");
  else if(a==="start-flash")startFlash();
  else if(a==="start-flash-filtered"){const a2=filteredDeckWords(); if(a2.length)startFlash(a2);else toast("這個篩選沒有單字")}
  else if(a==="start-match-filtered"){const a2=filteredDeckWords(); if(a2.length>=2)startMatch(a2);else toast("至少需要 2 個單字")}
  else if(a==="start-quiz-filtered"){const a2=filteredDeckWords(); if(a2.length)startQuiz(a2);else toast("這個篩選沒有單字")}
  else if(a==="start-cloze-filtered"){const a2=filteredDeckWords(); if(a2.length)startCloze(a2);else toast("這個篩選沒有單字")}
  else if(a==="tier-filter"){activeTierFilter=b.dataset.tier;renderDeck()}
  else if(a==="category-filter"){activeCategoryFilter=b.dataset.category;renderDeck()}
  else if(a==="flip"){flashFlipped=!flashFlipped;renderFlash()}
  else if(a==="rate"){rateWord(flash[flashIndex],Number(b.dataset.rate));flashIndex++;flashFlipped=false;renderFlash()}
  else if(a==="start-match")startMatch();
  else if(a==="match-pick")pickMatch(Number(b.dataset.index));
  else if(a==="start-quiz")startQuiz();
  else if(a==="quiz-answer")answerQuiz(b.dataset.value);
  else if(a==="quiz-next"){quizState.i++;quizState.dir=null;renderQuiz()}
  else if(a==="start-cloze")startCloze();
  else if(a==="cloze-answer")answerCloze(b.dataset.value);
  else if(a==="cloze-next"){clozeState.i++;clozeState.answered=false;clozeState.answer=null;renderCloze()}
  else if(a==="word-detail")openDetail(b.dataset.id);
  else if(a==="speak"){e.stopPropagation();speak(b.dataset.word)}
  else if(a==="toggle-fav"){e.stopPropagation();toggleFav(b.dataset.id)}
  else if(a==="quick-review"){
    const due=priorityWords(words.filter(w=>progress[w.id]?.due&&progress[w.id].due<=now()));
    const fallbackDeck=deckWords(Math.min(deckCount(),Math.max(1,Math.floor(globalStats().seen/50)+1)));
    startFlash(due.length?due:priorityWords(fallbackDeck))
  }
  else if(a==="review-list")reviewList(b.dataset.kind);
  else if(a==="study-tier"){
    const arr=words.filter(w=>w.tier===b.dataset.tier);
    startFlash(arr.length?arr:words);
  }
  else if(a==="study-tier-deck"){
    const arr=deckWords(currentDeck).filter(w=>w.tier===b.dataset.tier);
    if(arr.length) startFlash(arr); else toast("這個 Part 沒有這一層單字");
  }
  else if(a==="load-full")loadFull();
  else if(a==="import-dataset")document.getElementById("importDataset").click();
  else if(a==="clear-data")clearData();
  else if(a==="export-progress")exportProgress();
  else if(a==="import-progress")document.getElementById("importProgress").click();
  else if(a==="reset-progress")resetProgress();
});
document.querySelectorAll("#nav button").forEach(b=>b.addEventListener("click",()=>show(b.dataset.nav)));
document.getElementById("statsBtn").onclick=()=>show("stats");
document.getElementById("themeBtn").onclick=toggleTheme;
document.getElementById("modalClose").onclick=closeModal;
document.getElementById("modal").addEventListener("click",e=>{if(e.target.id==="modal")closeModal()});
document.getElementById("importProgress").onchange=e=>{if(e.target.files[0])importProgressFile(e.target.files[0]);e.target.value=""};
document.getElementById("importDataset").onchange=e=>{if(e.target.files[0])importDatasetFile(e.target.files[0]);e.target.value=""};

(function init(){
  // Strict v3 migration: delete only the OLD word-cache database.
  // Learning progress is stored separately in localStorage and is preserved.
  try{indexedDB.deleteDatabase("toeic900_standalone_db")}catch(e){}
  // Critical for Android content:// pages:
  // render the built-in app FIRST. IndexedDB is optional background enhancement only.
  applyTheme();
  renderHome();
  Promise.race([
    idbGet(DATA_KEY),
    new Promise(resolve=>setTimeout(()=>resolve(null),1200))
  ]).then(cached=>{
    if(Array.isArray(cached)&&cached.length>=50){
      words=cached; fullData=true;
      if(currentScreen==="home"||currentScreen==="decks"||currentScreen==="settings") render(currentScreen);
    }
  }).catch(()=>{});
})();


// ================================
// PWA INSTALL / SERVICE WORKER
// ================================
let deferredInstallPrompt = null;

function isStandaloneMode(){
  return window.matchMedia("(display-mode: standalone)").matches ||
         window.navigator.standalone === true;
}

function updateInstallButton(){
  const btn = document.getElementById("installBtn");
  if(!btn) return;
  btn.style.display = (!isStandaloneMode() && deferredInstallPrompt) ? "" : "none";
}

window.addEventListener("beforeinstallprompt", (event)=>{
  event.preventDefault();
  deferredInstallPrompt = event;
  updateInstallButton();
});

window.addEventListener("appinstalled", ()=>{
  deferredInstallPrompt = null;
  updateInstallButton();
  try{ toast("TOEIC 900 已安裝"); }catch(e){}
});

async function requestInstall(){
  if(isStandaloneMode()){
    try{ toast("目前已經是安裝模式"); }catch(e){}
    return;
  }
  if(deferredInstallPrompt){
    deferredInstallPrompt.prompt();
    try{ await deferredInstallPrompt.userChoice; }catch(e){}
    deferredInstallPrompt = null;
    updateInstallButton();
    return;
  }
  const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
  if(isIOS){
    alert("iPhone / iPad：請點 Safari 的分享按鈕，再選「加入主畫面」。");
  }else if(location.protocol === "file:" || location.protocol === "content:"){
    alert("要安裝 App，請先把這個 PWA 資料夾部署到 HTTPS 網址，再用 Chrome 開啟。直接開本機 HTML 無法安裝。");
  }else if(!window.isSecureContext){
    alert("PWA 安裝需要 HTTPS 安全連線。");
  }else{
    alert("瀏覽器目前尚未提供安裝提示。請稍等幾秒後重試，或從瀏覽器選單選擇「安裝應用程式」。");
  }
}

const installBtn = document.getElementById("installBtn");
if(installBtn) installBtn.addEventListener("click", requestInstall);

if("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost")){
  window.addEventListener("load", ()=>{
    navigator.serviceWorker.register("./service-worker.js", {scope:"./"})
      .catch(err=>console.warn("Service worker registration failed:",err));
  });
}
